def building_of(name: str) -> str:
    """'cookery4' / 'cookery4_furnished' -> 'cookery'"""
    import re
    return re.sub(r"\d.*$", "", name)


def recipe(name: str):
    return BUILDINGS.get(building_of(name))


def theme(name: str):
    r = recipe(name)
    return THEMES[r["theme"]] if r else None
